def _install_eslint(self, bootstrap_dir):
    """Install the ESLint distribution.

    :rtype: string
    """
    if not os.path.exists(bootstrap_dir):
      os.makedirs(bootstrap_dir)

    eslint_zip = os.path.join(bootstrap_dir, 'eslint.zip')
    if not os.path.exists(eslint_zip):
      with open(eslint_zip, 'w') as f:
        f.write(self.eslint_zip)

    if not os.path.exists(os.path.join(bootstrap_dir, 'eslint')):
      with zipfile.ZipFile(eslint_zip) as z:
        z.extractall(bootstrap_dir)

    return os.path.join(bootstrap_dir, 'eslint')

